def dfs(grid, start, end, visited=None):
    if visited is None:
        visited = set()

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]  # right, down, up, left

    def is_valid_move(r, c):
        if (
            r < 0 or c < 0 or r >= rows or c >= cols
            or grid[r][c] == 'X'  # Assuming 'X' represents an obstacle
            or (r, c) in visited
        ):
            return False
        return True

    def dfs_recursive(r, c):
        if (r, c) == end:
            return True
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid_move(nr, nc):
                if dfs_recursive(nr, nc):
                    return True
        return False

    return dfs_recursive(start[0], start[1])

