    ['X', 'X', 'X', 'X'],
    ['X', 'X', 'E', 'X'],
    ['X', 'X', 'X', 'X']
]
start = (0, 0)  # Start point
end = (2, 3)    # End point

if dfs(grid, start, end):
    print("Path found!")
else:
